+class InternalQueryTaskTest {
+    @Test
+    void shouldNotAcceptNullDriverOnInstantiation() {
+        assertThrows(
+                NullPointerException.class,
+                () -> new InternalQueryTask(null, new Query("string"), QueryConfig.defaultConfig()));
