+
+    @Test
+    void shouldUpdateParameters() {
+        // GIVEN
+        var query = new Query("string");
+        var params = Map.<String, Object>of("$param", "value");
+        var queryTask = new InternalQueryTask(mock(Driver.class), query, QueryConfig.defaultConfig());
