+                arguments(new byte[] {127}, 127L),
+                arguments(new byte[] {(byte) 0b00010110, 1}, 150L),
+                arguments(new byte[] {127, 127, 127, 127, (byte) 0b00000111}, Integer.MAX_VALUE),
