+
+    @Override
+    protected MessageFormat.Reader newReader( PackInput input )
+    {
+        return BoltProtocolV44.INSTANCE.createMessageFormat().newReader( input );
+    }
+
+    private Message record( Value value )
+    {
+        return new RecordMessage( new Value[]{value} );
+    }
